export const useAgentsStore = create<AgentsState>()(
    persist(
        (set, get) => ({
            agents: [DEFAULT_AGENT],
            _hasHydrated: false,
            // ... actions
        }),
        {
            name: 'via-gent-agents',
            version: 1,
            onRehydrateStorage: () => (state) => {
                state?.setHasHydrated(true);
            },
        }
    )
);

export const useProviderStore = create<ProviderState>()(
    persist(
        (set, get) => ({ /* state and actions */ }),
        {
            name: 'via-gent-providers',
            storage: createJSONStorage(() => createDexieStorage('providerConfigs')),
            partialize: (state) => ({
                providers: state.providers,
                activeProviderId: state.activeProviderId,
                modelSettings: state.modelSettings
            }),
            onRehydrateStorage: () => (state) => {
                if (state) {
                    if (!state.providers || state.providers.length === 0) {
                        state.providers = INITIAL_PROVIDERS;
                    }
                }
            }
        }
    )
);

export function createDexieStorage(tableName: keyof typeof db): { 
    getItem: (name: string) => Promise<string | null>, 
    setItem: (name: string, value: string) => Promise<void>, 
    removeItem: (name: string) => Promise<void> 
} {
    const table = db[tableName] as Table<PersistedStateRecord, string>;
    return {
        getItem: async (name: string): Promise<string | null> => {
            const record = await table.get(name);
            return record ? JSON.stringify(record.state) : null;
        },
        setItem: async (name: string, value: string): Promise<void> => {
            await table.put({
                id: name,
                state: JSON.parse(value),
                updatedAt: new Date()
            });
        },
        removeItem: async (name: string): Promise<void> => {
            await table.delete(name);
        }
    };
}

